// Validate first: an empty or malformed contact_id must match NO client row (a comparison with '' would match every row whose column is blank).
const raw = String($('Trigger').first().json.contact_id || '').trim();
const ok = /^(tg:\d+|wa:\+\d+)$/.test(raw);
const formula = ok
  ? (raw.startsWith('tg:') ? "{telegram_chat_id}='" + raw.slice(3) + "'" : "{phone}='" + raw.slice(3) + "'")
  : "{client_id}='__no_such_client__'";
return [{ json: { formula } }];

// The owner message. The contact, the reason and the history are client- or agent-controlled: each is cleaned before it is interpolated,
// and the header (who, contact, reason, status) is built first so a long history can only use what is left of the budget.
const MAX = 3500; // Telegram allows 4096; notify_owner cuts at 4000 BEFORE escaping, so no < > & may reach it (they are replaced below)
const clean = (s, max) => {
  const t = String(s ?? '').replace(/[\u0000-\u001f\u007f-\u009f\u200b-\u200f\u2028-\u202e\u2066-\u2069\ufeff]/g, ' ')
    .replace(/[<>&]/g, c => ({ '<': '‹', '>': '›', '&': '＆' }[c])).replace(/\s+/g, ' ').trim();
  const a = Array.from(t);
  return a.length > max ? a.slice(0, max - 1).join('') + '…' : t;
};
const inp = $('Trigger').first().json;
const contact = String(inp.contact_id ?? '').trim();
const contactOk = /^(tg:\d+|wa:\+\d+)$/.test(contact);
const client = $('Client').first().json || {};
let state;
if (client.error) state = 'client lookup FAILED - nothing was flagged';
else if (!client.id) state = 'contact not on file - nothing was flagged';
else {
  let flagged = false;
  try { const f = $('Flag Escalated').first().json; flagged = !!f.id && !f.error; } catch (e) { /* node did not run */ }
  state = flagged ? 'client flagged escalated' : 'WARNING: could not set the client status to escalated - flag them by hand';
}
const name = clean((client.fields || {}).name, 60) || (client.id ? 'unnamed client' : 'unknown contact');
const who = contactOk ? contact : (clean(contact, 80) || 'none') + ' - INVALID contact_id';
const head = `🚨 Escalation — ${name} (${who})\nReason: ${clean(inp.reason, 500) || '(none given)'}\nStatus: ${state}\n---`;
// History rows arrive newest first. A row that is not JSON, or has another shape, is skipped.
const items = $input.all().map(i => i.json || {});
const failed = items.some(r => r.error); // a failed query comes back as one item whose .message is the ERROR TEXT and which has .error: never treat it as history
const textOf = c => typeof c === 'string' ? c : Array.isArray(c) ? c.map(p => typeof p === 'string' ? p : (p && p.type === 'text' && typeof p.text === 'string' ? p.text : '')).join(' ') : '';
const lines = [];
for (const r of items) {
  if (r.error) continue;
  try {
    let m = r.message;
    if (typeof m === 'string') m = JSON.parse(m);
    if (!m || typeof m !== 'object') continue;
    const speaker = m.type === 'human' ? 'Client' : m.type === 'ai' ? 'Bot' : null;
    if (!speaker) continue;
    const body = clean(textOf(m.data && m.data.content !== undefined ? m.data.content : m.content), 300);
    if (body) lines.push(`${speaker}: ${body}`);
  } catch (e) { /* skip */ }
}
const room = MAX - head.length - 1 - 45; // 45 = room for the "earlier messages not shown" line
const kept = [];
let used = 0;
for (const l of lines) { if (used + l.length + 1 > room) break; kept.push(l); used += l.length + 1; }
const omitted = lines.length - kept.length;
const body = kept.length
  ? (omitted ? `(${omitted} earlier message${omitted > 1 ? 's' : ''} not shown)\n` : '') + kept.reverse().join('\n')
  : (failed ? '(conversation history unavailable)' : '(no conversation history yet)');
return [{ json: { text: head + '\n' + body } }];
